import{_ as t,o as i,c as o,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"pinia-mini vs pinia：差异地图","description":"","frontmatter":{"title":"pinia-mini vs pinia：差异地图"},"headers":[],"relativePath":"pinia-course/12-pinia-vs-mini.md","filePath":"pinia-course/docs/12-pinia-vs-mini.md"}'),d={name:"pinia-course/12-pinia-vs-mini.md"};function s(r,e,c,n,p,l){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="pinia-mini-vs-pinia-差异地图" tabindex="-1">pinia-mini vs pinia：差异地图 <a class="header-anchor" href="#pinia-mini-vs-pinia-差异地图" aria-label="Permalink to &quot;pinia-mini vs pinia：差异地图&quot;">​</a></h1><p>你刚用十二章从零写出了一个功能完备的 pinia-mini——但打开真仓库的 <code>packages/pinia/src/store.ts</code>，970 行，比你整个伴生实现还多一半，而且里面近一半的东西你没见过：<code>_hmrPayload</code>、<code>hotUpdate</code>、<code>ACTION_MARKER</code>、<code>diagnostics</code>、<code>__DEV__</code> 分支……读源码迷路的根源不是难度，是<strong>没有地图</strong>：不知道多出来的每一块各自保卫什么、为什么可以不在。这一章就是那张地图——逐 API 对照 mini 与真 pinia，给每块「多出来的代码」标注存在理由，最后给出啃真源码的推荐入口顺序。</p><h2 id="总量对照" tabindex="-1">总量对照 <a class="header-anchor" href="#总量对照" aria-label="Permalink to &quot;总量对照&quot;">​</a></h2><p>先看数字。mini 的 <code>src/</code> 共 678 行；真 pinia 的 <code>src/</code>（不含 devtools 目录与测试）2933 行：</p><table tabindex="0"><thead><tr><th>模块</th><th>mini</th><th>真 pinia</th><th>差距主要来自</th></tr></thead><tbody><tr><td>store.ts</td><td>404</td><td>970</td><td>HMR、开发警告、this 重绑、runWithContext</td></tr><tr><td>types.ts</td><td>102</td><td>723</td><td>四层泛型的完整类型推导</td></tr><tr><td>mapHelpers.ts</td><td>—</td><td>554</td><td>Vuex 兼容层（mini 整个不做）</td></tr><tr><td>rootStore.ts</td><td>33</td><td>172</td><td>getActivePinia 的 SSR 警告、接口文档</td></tr><tr><td>storeToRefs.ts</td><td>30</td><td>116</td><td>类型层（运行时逻辑几乎等价）</td></tr><tr><td>createPinia.ts</td><td>55</td><td>79</td><td>devtools 注册</td></tr><tr><td>subscriptions.ts</td><td>38</td><td>33</td><td>几乎一致</td></tr></tbody></table><p>两个立刻能读出的事实：<strong>运行时逻辑的差距远小于行数差距</strong>（storeToRefs 30 vs 116，多出的 90 行是类型）；<strong>三块真源码 mini 整体不做</strong>（mapHelpers、hmr、devtools），它们是「生态与开发体验」而不是「内核」。</p><h2 id="逐-api-差异对照" tabindex="-1">逐 API 差异对照 <a class="header-anchor" href="#逐-api-差异对照" aria-label="Permalink to &quot;逐 API 差异对照&quot;">​</a></h2><h3 id="createpinia-disposepinia" tabindex="-1">createPinia / disposePinia <a class="header-anchor" href="#createpinia-disposepinia" aria-label="Permalink to &quot;createPinia / disposePinia&quot;">​</a></h3><p>mini 55 行 vs 真 79 行。差异几乎只有一处：<code>registerPiniaDevtools(app, pinia)</code>——浏览器里按装 Vue Devtools 才走的注册分支（<code>__USE_DEVTOOLS__ &amp;&amp; IS_CLIENT</code> 双守卫）。存在理由：devtools 的时间旅行依赖 pinia 主动上报 store 树。为什么可以不在：它是纯消费者，不改变任何运行时语义。你的 mini 装不上 devtools，但行为完全一致。</p><h3 id="definestore-usestore" tabindex="-1">defineStore / useStore <a class="header-anchor" href="#definestore-usestore" aria-label="Permalink to &quot;defineStore / useStore&quot;">​</a></h3><p>mini 的 useStore 与真 pinia 主干逐字对应（三级回退、查表、登记）。多出的三块：</p><ul><li><code>__TEST__</code> 分支：测试模式下忽略传入的 pinia 参数，强制走活动容器——让 <code>createTestingPinia</code> 能劫持一切取用。测试基建，非内核。</li><li><code>useStore._pinia = pinia</code>（DEV）：给 devtools 从组件实例反查 pinia 用的注记。</li><li>HMR 分支：<code>hot._hotUpdate(newStore)</code>——开发时改了 store 定义文件，Vite 热更新不刷新页面、现场状态原样迁移到新定义。<code>_hmrPayload</code>（actions/getters/state 的登记册）就是为它准备的。存在理由：没有它，开发时每次改 store 都丢状态重走流程。为什么可以不在：它只影响开发时的刷新体验，生产构建里整块被 tree-shake。</li></ul><h3 id="createsetupstore-分类循环" tabindex="-1">createSetupStore（分类循环） <a class="header-anchor" href="#createsetupstore-分类循环" aria-label="Permalink to &quot;createSetupStore（分类循环）&quot;">​</a></h3><p>mini 404 行 store.ts 的主干与真 pinia 相同，但四个细节被 mini 刻意简化：</p><ol><li><code>ACTION_MARKER</code> / <code>ACTION_NAME</code> 两个 Symbol——真 pinia 给 action 外壳打的标记，<code>hotUpdate</code> 时识别「这个函数已经是包装过的」防止套两层壳。mini 没有 HMR，不需要。</li><li><code>this</code> 重绑：真 pinia 的外壳用 <code>fn.apply(this &amp;&amp; this.$id === $id ? this : store, args)</code>——HMR 期间新 store 调旧 action 时绑回新 store。mini 恒绑 <code>store</code>。</li><li>两个静音标志 vs 一个：第 8 章末尾说过——真 pinia 有 <code>isListening</code> 与 <code>isSyncListening</code> 双标志，因为它的 sync watcher 在 patch 结束瞬间就要恢复收听；mini 统一 nextTick 恢复，边角时序略钝，主行为一致。</li><li>hydration 的守卫差异：真 pinia 用 <code>shouldHydrate</code>（配合 <code>skipHydrate()</code> 逃生舱，允许 setup 返回「响应式但不是状态」的东西跳过水合）；mini 用 <code>key in initialState</code>——语义更直白，边角少一层可配置性。</li></ol><h3 id="patch-reset-state" tabindex="-1">$patch / $reset / $state <a class="header-anchor" href="#patch-reset-state" aria-label="Permalink to &quot;$patch / $reset / $state&quot;">​</a></h3><p>mini 与真 pinia 的 <code>mergeReactiveObjects</code> 逻辑一致（含 Map/Set 分支的「服务 hydration」定位——第 7 章我们顺着官方测试还原了这个语义）。真 pinia 多出的是 <code>$patch</code> 里对 <code>debuggerEvents</code> 的收集——把每次变更的底层事件（哪个 key、新旧值）打包进订阅事件，devtools 时间旅行的数据源。又是纯消费者。</p><h3 id="subscribe-onaction-dispose" tabindex="-1">$subscribe / $onAction / $dispose <a class="header-anchor" href="#subscribe-onaction-dispose" aria-label="Permalink to &quot;$subscribe / $onAction / $dispose&quot;">​</a></h3><p>subscriptions.ts 两边几乎逐行相同（38 vs 33，mini 注释多）。真 pinia 多两处：<code>$subscribe</code> 对同一回调重复订阅返回 noop 并在 DEV 报警（mini 返回空函数但不报警）；订阅事件里的 <code>events</code> 字段（同上，devtools 数据源）。</p><h3 id="storetorefs" tabindex="-1">storeToRefs <a class="header-anchor" href="#storetorefs" aria-label="Permalink to &quot;storeToRefs&quot;">​</a></h3><p>运行时逻辑等价（第 9 章引过：真 pinia 的 <code>value?.effect</code> 判定与 <code>toRef</code>/<code>computed</code> 包装与 mini 相同）。多出的 90 行全是类型：<code>_ToStateRefs</code>/<code>_ToComputedRefs</code> 把「state→Ref、getter→ComputedRef、可写 getter→WritableComputedRef」表达到类型层。<strong>类型即文档</strong>——mini 用 <code>Record&lt;string, any&gt;</code> 换掉了这层表达，代价是 <code>count.value</code> 没有自动补全的 <code>number</code> 类型。</p><h3 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h3><p>管线五行一致。真 pinia 多两道 DEV 保险：插件返回「裸对象」的诊断警告（PINIA_R1006——裸对象被 reactive 化后失去身份）、<code>app.runWithContext</code> 包裹（第 11 章第三道防线）。mini 都没做——前者是开发体验，后者是 SSR 边角加固。</p><h3 id="mini-完全不做的三块" tabindex="-1">mini 完全不做的三块 <a class="header-anchor" href="#mini-完全不做的三块" aria-label="Permalink to &quot;mini 完全不做的三块&quot;">​</a></h3><ul><li>mapHelpers.ts（554 行）：<code>mapState</code>/<code>mapActions</code>/<code>mapStores</code>——Vue 2 选项式组件的 Vuex 风格语法。Vue 3 组合式 API 下的新代码基本不用，纯兼容层。</li><li>hmr.ts（122 行）：热更新的状态迁移（<code>patchObject</code> 按 option/setup 两种语法的差异化迁移，本章开头那批 <code>_hotUpdate</code> 细节的实现所在）。</li><li>devtools/（7 个文件）：与 Vue Devtools 面板的协议对接。</li></ul><p>三块的共同点：都挂在内核已有的钩子上，不碰内核路径。这就是「内核与生态分层」的价值——你写的 mini 少了它们依然是一个正确的 pinia。</p><h2 id="类型层的差距-最大也最值得看" tabindex="-1">类型层的差距（最大也最值得看） <a class="header-anchor" href="#类型层的差距-最大也最值得看" aria-label="Permalink to &quot;类型层的差距（最大也最值得看）&quot;">​</a></h2><p>723 行的 types.ts 是真 pinia 最大的单文件，也是 mini 刻意绕开的山：<code>defineStore</code> 的四层泛型 <code>Id/S/G/A</code>、<code>Store&lt;Id, S, G, A&gt;</code> 的交叉类型、Setup Store 的 <code>_ExtractXxxFromSetupStore</code> 条件类型——全为了一个目标：<code>const { count, double, increment } = store</code> 每个都有精确类型，<code>store.typo</code> 编译期报错。mini 的测试里那些 <code>this: any</code> 标注，就是绕开这座山付的学费。想进阶类型体操，这个文件是比任何教程都好的教材——但建议啃完运行时再回来。</p><h2 id="啃真源码的推荐入口" tabindex="-1">啃真源码的推荐入口 <a class="header-anchor" href="#啃真源码的推荐入口" aria-label="Permalink to &quot;啃真源码的推荐入口&quot;">​</a></h2><p>按依赖方向、由短到长：</p><ol><li><code>subscriptions.ts</code>（33 行）——与你的版本并排读，热身。</li><li><code>createPinia.ts</code>（79 行）——看 devtools 注册挂在哪。</li><li><code>rootStore.ts</code>（172 行）——看 getActivePinia 的 SSR 警告与你的第 11 章对照。</li><li><code>storeToRefs.ts</code>（116 行）——运行时部分你会秒懂，然后顺着类型往下读。</li><li><code>store.ts</code>（970 行）——<strong>跳着读</strong>：先读 <code>defineStore</code>→<code>createSetupStore</code> 主干（与你的一一对应），再挑一块外围（建议 HMR：<code>_hmrPayload</code> 与 <code>hotUpdate</code>，用第 5、6 章的「分类」与「hydration」概念去读，会发现它就是「把分类登记册拿来重放」）。</li><li>最后才是 <code>types.ts</code>——把它当类型体操教材，不当必读物。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>真 pinia = 你的 mini + 三类增量：<strong>开发体验</strong>（HMR、devtools、诊断警告）、<strong>生态兼容</strong>（mapHelpers）、<strong>类型表达</strong>（723 行 types）。三类都挂在内核已有钩子上，不碰内核路径——所以 mini 才能以 678 行达到行为等价。这张地图的用法不是「背差异」，是带着它进真源码：每读一块，先问「它挂在哪个钩子上、保卫什么」——问得出来，你就没迷路。</p>',33)])])}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
